Then, {\normalfont \COSV} (Alg.~\ref{alg:COSV}) satisfies the \emph{gap-dependent} regret upper bound
    \begin{equation}
    \label{eq:COSVGapDep}
        \bE[R_T] 
        = \tilde{O}\bigg(\log(m)^2\sum_{i=1}^d\frac{m\SSigma_{i,i}}{\Delta_{i,\min}} \bigg)\,,
    \end{equation}
    where $\Delta_{i,\min}=\min\{\Delta_a,\ a\in\cA \text{ such that } i\in a \}$

and the \emph{gap-free} regret upper bound
    \begin{equation}
        \bE[R_T] = \tilde{O}\bigg(\log(m)\sqrt{T}\sqrt{\textstyle m \sum_{i=1}^d\SSigma_{i,i}} \bigg) \,.
    \end{equation}
